#[doc = "An interface for querying the microphone and accessing data read from it.\n\n# See also\n\n> [`RETRO_ENVIRONMENT_GET_MICROPHONE_INTERFACE`]\n"]
#[repr(C)]
#[derive(Debug, Copy, Clone)]
pub struct retro_microphone_interface {
    #[doc = "The version of this microphone interface.\nSet by the core to request a particular version,\nand set by the frontend to indicate the returned version.\n0 indicates that the interface is invalid or uninitialized.\n"]
    pub interface_version: ::core::ffi::c_uint,
    #[doc = "Initializes a new microphone.\nAssuming that microphone support is enabled and provided by the frontend,\ncores may call this function whenever necessary.\nA microphone could be opened throughout a core's lifetime,\nor it could wait until a microphone is plugged in to the emulated device.\n\nThe returned handle will be valid until it's freed,\neven if the audio driver is reinitialized.\n\nThis function is not guaranteed to be thread-safe.\n\n# Arguments\n\n* `args` \\[in\\] - Parameters used to create the microphone.\nMay be `NULL,` in which case the default value of each parameter will be used.\n\n# Returns\n\n* Pointer to the newly-opened microphone,\nor `NULL` if one couldn't be opened.\nThis likely means that no microphone is plugged in and recognized,\nor the maximum number of supported microphones has been reached.\n\n> **Note** Microphones are _inactive_ by default;\nto begin capturing audio, call `set_mic_state.`\n\n# See also\n\n> [`retro_microphone_params_t`]\n"]
    pub open_mic: retro_open_mic_t,
    #[doc = "Closes a microphone that was initialized with `open_mic.`\nCalling this function will stop all microphone activity\nand free up the resources that it allocated.\nAfterwards, the handle is invalid and must not be used.\n\nA frontend may close opened microphones when unloading content,\nbut this behavior is not guaranteed.\nCores should close their microphones when exiting, just to be safe.\n\n# Arguments\n\n* `microphone` - Pointer to the microphone that was allocated by `open_mic.`\nIf `NULL,` this function does nothing.\n\n> **Note** The handle might be reused if another microphone is opened later.\n"]
    pub close_mic: retro_close_mic_t,
    #[doc = "Returns the configured parameters of this microphone.\nThese may differ from what was requested depending on\nthe driver and device configuration.\n\nCores should check these values before they start fetching samples.\n\nWill not change after the mic was opened.\n\n# Arguments\n\n* `microphone` \\[in\\] - Opaque handle to the microphone\nwhose parameters will be retrieved.\n* `params` \\[out\\] - The parameters object that the\nmicrophone's parameters will be copied to.\n\n# Returns\n\n* `true` if the parameters were retrieved,\n`false` if there was an error.\n"]
    pub get_params: retro_get_mic_params_t,
    #[doc = "Enables or disables the given microphone.\nMicrophones are disabled by default\nand must be explicitly enabled before they can be used.\nDisabled microphones will not process incoming audio samples,\nand will therefore have minimal impact on overall performance.\nCores may enable microphones throughout their lifetime,\nor only for periods where they're needed.\n\nCores that accept microphone input should be able to operate without it;\nwe suggest substituting silence in this case.\n\n# Arguments\n\n* `microphone` - Opaque handle to the microphone\nwhose state will be adjusted.\nThis will have been provided by `open_mic.`\n* `state` - `true` if the microphone should receive audio input,\n`false` if it should be idle.\n\n# Returns\n\n* `true` if the microphone's state was successfully set,\n`false` if `microphone` is invalid\nor if there was an error.\n"]
    pub set_mic_state: retro_set_mic_state_t,
    #[doc = "Queries the active state of a microphone at the given index.\nWill return whether the microphone is enabled,\neven if the driver is paused.\n\n# Arguments\n\n* `microphone` - Opaque handle to the microphone\nwhose state will be queried.\n\n# Returns\n\n* `true` if the provided `microphone` is valid and active,\n`false` if not or if there was an error.\n"]
    pub get_mic_state: retro_get_mic_state_t,
    #[doc = "Retrieves the input processed by the microphone since the last call.\n_Must_ be called every frame unless `microphone` is disabled,\nsimilar to how `retro_audio_sample_batch_t` works.\n\n# Arguments\n\n* `microphone` \\[in\\] - Opaque handle to the microphone\nwhose recent input will be retrieved.\n* `samples` \\[out\\] - The buffer that will be used to store the microphone's data.\nMicrophone input is in mono (i.e. one number per sample).\nShould be large enough to accommodate the expected number of samples per frame;\nfor example, a 44.1kHz sample rate at 60 FPS would require space for 735 samples.\n* `num_samples` \\[in\\] - The size of the data buffer in samples (_not_ bytes).\nMicrophone input is in mono, so a \"frame\" and a \"sample\" are equivalent in length here.\n\n# Returns\n\n* The number of samples that were copied into `samples.`\nIf `microphone` is pending driver initialization,\nthis function will copy silence of the requested length into `samples.`\n\nWill return -1 if the microphone is disabled,\nthe audio driver is paused,\nor there was an error.\n"]
    pub read_mic: retro_read_mic_t,
}
#[repr(u32)]
#[doc = "Describes how a device is being powered.\n\n# See also\n\n> [`RETRO_ENVIRONMENT_GET_DEVICE_POWER`]\n"]
#[derive(Debug, Copy, Clone, Hash, PartialEq, Eq)]
pub enum retro_power_state {
    #[doc = "Indicates that the frontend cannot report its power state at this time,\nmost likely due to a lack of support.\n\n`RETRO_ENVIRONMENT_GET_DEVICE_POWER` will not return this value;\ninstead, the environment callback will return `false.`\n"]
    RETRO_POWERSTATE_UNKNOWN = 0,
    #[doc = "Indicates that the device is running on its battery.\nUsually applies to portable devices such as handhelds, laptops, and smartphones.\n"]
    RETRO_POWERSTATE_DISCHARGING = 1,
    #[doc = "Indicates that the device's battery is currently charging.\n"]
    RETRO_POWERSTATE_CHARGING = 2,
    #[doc = "Indicates that the device is connected to a power source\nand that its battery has finished charging.\n"]
    RETRO_POWERSTATE_CHARGED = 3,
    #[doc = "Indicates that the device is connected to a power source\nand that it does not have a battery.\nThis usually suggests a desktop computer or a non-portable game console.\n"]
    RETRO_POWERSTATE_PLUGGED_IN = 4,
}
#[doc = "Describes the power state of the device running the frontend.\n\n# See also\n\n> [`RETRO_ENVIRONMENT_GET_DEVICE_POWER`]\n"]
